local Players=game:GetService("Players")
local StarterGui=game:GetService("StarterGui")
local CoreGui=game:GetService("CoreGui")
local Lighting=game:GetService("Lighting")
local LP=Players.LocalPlayer

local env=(getgenv and getgenv()) or _G
env.UltraNovaGeneration=(env.UltraNovaGeneration or 0)+1

-- Cross-parent cleanup so re-running the loader never builds a tower of old menus.
local CLEAN_NAMES={
    UltraNovaBoot=true,
    UltraNovaHub=true,
    UltraNovaAimOverlay=true,
    UltraNovaCheatPlusHUD=true,
    UltraNovaVisualFX=true,
}
local function cleanParent(parent)
    if not parent then return end
    pcall(function()
        for _,child in ipairs(parent:GetChildren()) do
            if CLEAN_NAMES[child.Name] then child:Destroy() end
        end
    end)
end
cleanParent(LP:WaitForChild("PlayerGui"))
cleanParent(CoreGui)
pcall(function() if gethui then cleanParent(gethui()) end end)
pcall(function()
    local f=workspace:FindFirstChild("UltraNovaClientFX")
    if f then f:Destroy() end
    local wf=workspace:FindFirstChild("UltraNovaWallBreakFX")
    if wf then wf:Destroy() end
    for _,d in ipairs(workspace:GetChildren()) do
        if d.Name=="UltraNovaBlinkEcho" or d.Name=="UltraNovaParkourRing" or d.Name=="UltraNovaEnergyRing" then
            d:Destroy()
        end
    end
    local blur=Lighting:FindFirstChild("UltraNovaPhaseBlur")
    if blur then blur:Destroy() end
end)

local function makeLoader()
    local pg=LP:WaitForChild("PlayerGui")
    local old=pg:FindFirstChild("UltraNovaBoot")
    if old then old:Destroy() end
    local g=Instance.new("ScreenGui")
    g.Name="UltraNovaBoot"; g.ResetOnSpawn=false; g.IgnoreGuiInset=false; g.Parent=pg
    local f=Instance.new("Frame")
    f.Size=UDim2.new(.82,0,0,116); f.Position=UDim2.new(.09,0,.5,-58)
    f.BackgroundColor3=Color3.fromRGB(10,7,24); f.Parent=g
    Instance.new("UICorner",f).CornerRadius=UDim.new(0,16)
    local st=Instance.new("UIStroke",f); st.Color=Color3.fromRGB(151,77,255); st.Thickness=1.4
    local t=Instance.new("TextLabel")
    t.Size=UDim2.new(1,-22,1,-22); t.Position=UDim2.fromOffset(11,11)
    t.BackgroundTransparency=1; t.TextColor3=Color3.fromRGB(246,246,255)
    t.TextWrapped=true; t.TextSize=15; t.Font=Enum.Font.GothamBold
    t.Text="UltraNova v3.2 • AURA+PARKOUR BUILD\nPreparazione..."; t.Parent=f
    return g,t
end

local BootGui,BootText=makeLoader()
local function status(s) BootText.Text="UltraNova v3.2 • AURA+PARKOUR BUILD\n"..tostring(s) end
local function fatal(stage,err)
    local msg=tostring(stage).."\n"..tostring(err)
    status("❌ "..msg)
    pcall(function() StarterGui:SetCore("SendNotification",{Title="UltraNova v3.2",Text=msg,Duration=10}) end)
    pcall(function() if setclipboard then setclipboard(msg) end end)
end

