ontrast=.08; cc.Saturation=-.08; cc.Parent=Lighting\n    end\nend)\n\nsection(VisualsPage,\"CROSSHAIR+\")\nbutton(VisualsPage,\"Colore crosshair / Crosshair Color\",function(b)\n    S.crosshairColorIndex=S.crosshairColorIndex%#ESP_PALETTE+1\n    local col=ESP_PALETTE[S.crosshairColorIndex]\n    CrossH.BackgroundColor3=col; CrossV.BackgroundColor3=col; CrossDot.BackgroundColor3=col; b.TextColor3=col\nend)\nslider(VisualsPage,\"Spessore crosshair / Thickness\",1,8,2,function(v)\n    S.crosshairThickness=v; CrossH.Size=UDim2.fromOffset(S.crosshairSize,v); CrossV.Size=UDim2.fromOffset(v,S.crosshairSize)\nend)\nslider(VisualsPage,\"Trasparenza crosshair / Opacity\",0,90,0,function(v)\n    S.crosshairOpacity=v/100; CrossH.BackgroundTransparency=S.crosshairOpacity; CrossV.BackgroundTransparency=S.crosshairOpacity; CrossDot.BackgroundTransparency=S.crosshairOpacity\nend)\n\nlocal skeletonPairsR15={{\"Head\",\"UpperTorso\"},{\"UpperTorso\",\"LowerTorso\"},{\"UpperTorso\",\"LeftUpperArm\"},{\"LeftUpperArm\",\"LeftLowerArm\"},{\"LeftLowerArm\",\"LeftHand\"},{\"UpperTorso\",\"RightUpperArm\"},{\"RightUpperArm\",\"RightLowerArm\"},{\"RightLowerArm\",\"RightHand\"},{\"LowerTorso\",\"LeftUpperLeg\"},{\"LeftUpperLeg\",\"LeftLowerLeg\"},{\"LowerTorso\",\"RightUpperLeg\"},{\"RightUpperLeg\",\"RightLowerLeg\"}}\nlocal skeletonPairsR6={{\"Head\",\"Torso\"},{\"Torso\",\"Left Arm\"},{\"Torso\",\"Right Arm\"},{\"Torso\",\"Left Leg\"},{\"Torso\",\"Right Leg\"}}\n\nRunService.RenderStepped:Connect(function()\n    Camera=workspace.CurrentCamera or Camera\n    local myRoot=root(); local centerBottom=Vector2.new(Camera.ViewportSize.X/2,Camera.ViewportSize.Y-5)\n    local rainbow=Color3.fromHSV((os.clock()*.13)%1,.85,1)\n    if S.rainbowEsp then S.espColor=rainbow end\n\n    for _,p in ipairs(Players:GetPlayers()) do\n        if p~=LP then\n            local o=getVisualObj(p); local c=p.Character; local pr=c and c:FindFirstChild(\"HumanoidRootPart\"); local head=c and c:FindFirstChild(\"Head\"); local h=c and c:FindFirstChildOfClass(\"Humanoid\")\n            local allowed=false; local distance=math.huge\n            if pr and myRoot then distance=(pr.Position-myRoot.Position).Magnitude; allowed=distance<=S.espMaxDistance end\n            if not allowed then hideVisual(o) else\n                local col=S.rainbowEsp and rainbow or S.espColor\n                local rp,ron=Camera:WorldToViewportPoint(pr.Position); local hp,hon=head and Camera:WorldToViewportPoint(head.Position) or rp,false\n                if ron and rp.Z>0 then\n                    if S.tracers then draw2DLine(o.Tracer,centerBottom,Vector2.new(rp.X,rp.Y),col,1.4) else o.Tracer.Visible=false end\n                    local height=math.max(28,math.abs(rp.Y-hp.Y)*2.7); local width=height*.55\n                    if S.boxEsp then o.Box.Position=UDim2.fromOffset(rp.X-width/2,rp.Y-height/2); o.Box.Size=UDim2.fromOffset(width,height); o.BoxStroke.Color=col; o.Box.Visible=true else o.Box.Visible=false end\n                    if S.healthBars and h then\n                        o.HealthBG.Position=UDim2.fromOffset(rp.X-width/2-7,rp.Y-height/2); o.HealthBG.Size=UDim2.fromOffset(4,height); o.Health.Size=UDim2.new(1,0,math.clamp(h.Health/math.max(1,h.MaxHealth),0,1),0); o.HealthBG.Visible=true\n                    else o.HealthBG.Visible=false end\n                    o.HL.Adornee=c; o.HL.FillColor=col; o.HL.OutlineColor=col; o.HL.FillTransparency=S.chams and .68 or 1; o.HL.OutlineTransparency=S.playerGlow and 0 or .45; o.HL.Enabled=S.chams or S.playerGlow\n                    for _,f in ipairs(o.Skel) do f.Visible=false end\n                    if S.skeletonEsp then\n                        local pairsList=(h and h.RigType==Enum.HumanoidRigType.R15) and skeletonPairsR15 or skeletonPairsR6\n                        for i,pair in ipairs(pairsList) do\n                            local a=c:FindFirstChild(pair[1]); local b=c:FindFirstChild(pair[2]); local f=o.Skel[i]\n                            if a and b and f then local ap,aon=Camera:WorldToViewportPoint(a.Position); local bp,bon=Camera:WorldToViewportPoint(b.Position); if aon and bon then draw2DLine(f,Vector2.new(ap.X,ap.Y),Vector2.new(bp.X,bp.Y),col,1.2) end end\n                        end\n                    end\n                else hideVisual(o) end\n            end\n        end\n    end\nend)\n\nPlayers.PlayerRemoving:Connect(function(p)\n    local o=ExtraVisualObjects[p]; if o then pcall(function() o.Tracer:Destroy(); o.Box:Destroy(); o.HealthBG:Destroy(); o.HL:Destroy(); for _,f in ipairs(o.Skel) do f:Destroy() end end); ExtraVisualObjects[p]=nil end\nend)\n\n--========================================================\n-- SHADERS WORLD FX ADD-ON\n--========================================================\nsection(Shaders,\"WORLD FX / SCENE CONTROL\")\nlocal Terrain=workspace:FindFirstChildOfClass(\"Terrain\")\nlocal OriginalWater = Terrain and {Color=Terrain.WaterColor,Transparency=Terrain.WaterTransparency,WaveSize=Terrain.WaterWaveSize,WaveSpeed=Terrain.WaterWaveSpeed,Reflectance=Terrain.WaterReflectance} or nil\nlocal Clouds=Terrain and Terrain:FindFirstChildOfClass(\"Clouds\")\n\nbutton(Shaders,\"Acqua: Realistic / Water\",function()\n    if Terrain then Terrain.WaterColor=Color3.fromRGB(34,104,145); Terrain.WaterTransparency=.22; Terrain.WaterReflectance=.45; Terrain.WaterWaveSize=.18; Terrain.WaterWaveSpeed=12 end\nend)\nbutton(Shaders,\"Acqua: Deep Space\",function()\n    if Terrain then Terrain.WaterColor=Color3.fromRGB(39,20,86); Terrain.WaterTransparency=.28; Terrain.WaterReflectance=.55; Terrain.WaterWaveSize=.14; Terrain.WaterWaveSpeed=8 end\nend)\nbutton(Shaders,\"Reset Acqua / Reset Water\",function()\n    if Terrain and OriginalWater then Terrain.WaterColor=OriginalWater.Color; Terrain.WaterTransparency=OriginalWater.Transparency; Terrain.WaterReflectance=OriginalWater.Reflectance; Terrain.WaterWaveSize=OriginalWater.WaveSize; Terrain.WaterWaveSpeed=OriginalWater.WaveSpeed end\nend)\nslider(Shaders,\"Ora del giorno / Time of Day\",0,24,math.floor(Lighting.ClockTime),function(v) Lighting.ClockTime=v end)\nslider(Shaders,\"Atmosphere Contrast\",0,50,10,function(v)\n    local cc=Lighting:FindFirstChild(\"UltraNovaManualContrast\") or Instance.new(\"ColorCorrectionEffect\"); cc.Name=\"UltraNovaManualContrast\"; cc.Parent=Lighting; cc.Contrast=v/100\nend)\nslider(Shaders,\"Saturazione / Saturation\",0,200,100,function(v)\n    local cc=Lighting:FindFirstChild(\"UltraNovaManualSaturation\") or Instance.new(\"ColorCorrectionEffect\"); cc.Name=\"UltraNovaManualSaturation\"; cc.Parent=Lighting; cc.Saturation=(v-100)/100\nend)\nbutton(Shaders,\"Nuvole cinematiche / Cinematic Clouds\",function()\n    if Terrain then\n        Clouds=Terrain:FindFirstChildOfClass(\"Clouds\") or Instance.new(\"Clouds\",Terrain); Clouds.Cover=.48; Clouds.Density=.55; Clouds.Color=Color3.fromRGB(220,214,238)\n    end\nend)\nbutton(Shaders,\"Nuvole space / Space Clouds\",function()\n    if Terrain then\n        Clouds=Terrain:FindFirstChildOfClass(\"Clouds\") or Instance.new(\"Clouds\",Terrain); Clouds.Cover=.62; Clouds.Density=.66; Clouds.Color=Color3.fromRGB(92,63,142)\n    end\nend)\n\n\n\nU.FreeCamPad = FreeCamPad\nU.setFreecam = setFreecam\nU.ExtraVisualGui = ExtraVisualGui\nU.VisualWorldFolder = VisualWorldFolder\n"},
    {"aura_fx","\nlocal UltraNovaGlobal = (getgenv and getgenv()) or _G\nlocal U = assert(UltraNovaGlobal.UltraNovaV32, \"UltraNova v3.2 core was not loaded\")\n\nlocal Players,RunService,TweenService,Lighting = U.Players,U.RunService,U.TweenService,U.Lighting\nlocal LP,Camera = U.LP,U.Camera\nlocal S,C = U.S,U.C\nlocal VisualsPage = U.VisualsPage\nlocal root,humanoid,character = U.root,U.humanoid,U.character\nlocal section,button,toggle,slider,corner,stroke,toast = U.section,U.button,U.toggle,U.slider,U.corner,U.stroke,U.toast\n\nS.novaTrail = S.novaTrail or false\nS.phaseMode = S.phaseMode or false\nS.auraReactor = S.auraReactor or false\nS.auraStyleIndex = S.auraStyleIndex or 1\nS.auraFormIndex = S.auraFormIndex or 1\nS.auraSound = (S.auraSound == nil) and true or S.auraSound\nS.auraSoundVolume = S.auraSoundVolume or 18\nS.auraColorIndex = S.auraColorIndex or 1\nS.auraIntensity = S.auraIntensity or 6\nS.auraSize = S.auraSize or 6\nS.auraPulseSpeed = S.auraPulseSpeed or 4\nS.cinematicMovementFx = S.cinematicMovementFx or false\nS.constellationRadar = S.constellationRadar or false\n\nlocal gen = UltraNovaGlobal.UltraNovaGeneration or 0\nlocal function alive()\n    return (UltraNovaGlobal.UltraNovaGeneration or 0) == gen and U.Gui and U.Gui.Parent\nend\n\npcall(function()\n    local old = U.GuiParent:FindFirstChild(\"UltraNovaVisualFX\")\n    if old then old:Destroy() end\nend)\npcall(function()\n    local old = workspace:FindFirstChild(\"UltraNovaClientFX\")\n    if old then old:Destroy() end\nend)\npcall(function()\n    local old = Lighting:FindFirstChild(\"UltraNovaPhaseBlur\")\n    if old then old:Destroy() end\nend)\n\nlocal FxGui = Instance.new(\"ScreenGui\")\nFxGui.Name = \"UltraNovaVisualFX\"\nFxGui.ResetOnSpawn = false\nFxGui.IgnoreGuiInset = false\nFxGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\nFxGui.Parent = U.GuiParent\n\nlocal FxFolder = Instance.new(\"Folder\")\nFxFolder.Name = \"UltraNovaClientFX\"\nFxFolder.Parent = workspace\n\nlocal function feedback(color)\n    local icon = U.NovaIcon\n    if not icon or not icon.Parent then return end\n    local oldColor = icon.BackgroundColor3\n    TweenService:Create(icon,TweenInfo.new(.08,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{\n        Rotation=-12,\n        BackgroundColor3=color or C.Cyan\n    }):Play()\n    task.delay(.1,function()\n        if icon and icon.Parent then\n            TweenService:Create(icon,TweenInfo.new(.2,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{\n                Rotation=0,\n                BackgroundColor3=oldColor\n            }):Play()\n        end\n    end)\nend\n\n\nlocal auraForms = {\n    {Name=\"SUPERNOVA\",Mode=\"STAR\"},\n    {Name=\"INFERNO\",Mode=\"FIRE\"},\n    {Name=\"ELECTRIC\",Mode=\"ELECTRIC\"},\n    {Name=\"VOID\",Mode=\"SMOKE\"},\n    {Name=\"ICE\",Mode=\"ICE\"},\n    {Name=\"BLACK HOLE\",Mode=\"BLACKHOLE\"},\n}\nlocal auraParts = {}\nlocal AuraLight=nil\nlocal AuraHighlight=nil\n\nlocal oldAuraSound=U.SoundService:FindFirstChild(\"UltraNovaAuraSound\")\nif oldAuraSound then oldAuraSound:Destroy() end\nlocal AuraSound=Instance.new(\"Sound\")\nAuraSound.Name=\"UltraNovaAuraSound\"\nAuraSound.Volume=0\nAuraSound.Looped=false\nAuraSound.Parent=U.SoundService\n\nlocal auraSoundProfiles={\n    {Id=\"rbxassetid://1845421369\",Speed=.92,Interval=5.2},\n    {Id=\"rbxasset://sounds/collide.wav\",Speed=.50,Interval=2.7},\n    {Id=\"rbxassetid://9114340342\",Speed=1.65,Interval=1.55},\n    {Id=\"rbxassetid://1845421369\",Speed=.58,Interval=5.8},\n    {Id=\"rbxasset://sounds/collide.wav\",Speed=1.32,Interval=3.6},\n    {Id=\"rbxassetid://1845421369\",Speed=.42,Interval=6.4},\n}\nlocal nextAuraSound=0\nlocal function playAuraPulse(force)\n    if not S.auraReactor or not S.auraSound then return end\n    local now=os.clock()\n    local profile=auraSoundProfiles[S.auraFormIndex] or auraSoundProfiles[1]\n    if not force and now<nextAuraSound then return end\n    nextAuraSound=now+profile.Interval\n    AuraSound:Stop()\n    AuraSound.SoundId=profile.Id\n    AuraSound.PlaybackSpeed=profile.Speed\n    AuraSound.Volume=math.clamp(S.auraSoundVolume/100,0,.65)\n    AuraSound:Play()\nend\n\ntask.spawn(function()\n    while alive() do\n        playAuraPulse(false)\n        task.wait(.22)\n    end\nend)\n\nlocal function destroyAura()\n    for _,p in ipairs(auraParts) do pcall(function() p:Destroy() end) end\n    auraParts={}\n    if AuraLight then AuraLight:Destroy(); AuraLight=nil end\n    if AuraHighlight then AuraHighlight:Destroy(); AuraHighlight=nil end\n    AuraSound:Stop()\nend\n\nlocal function decorateAuraPart(orb,form,color,index)\n    if form.Mode==\"FIRE\" then\n        orb.Shape=Enum.PartType.Ball\n        orb.Material=Enum.Material.Neon\n        orb.Transparency=.55\n        orb.Color=color\n        local fire=Instance.new(\"Fire\")\n        fire.Name=\"AuraFire\"\n        fire.Color=color\n        fire.SecondaryColor=Color3.fromRGB(255,65,12)\n        fire.Heat=0\n        fire.Size=1.8+(index%3)*.35\n        fire.Parent=orb\n    elseif form.Mode==\"ELECTRIC\" then\n        orb.Shape=Enum.PartType.Ball\n        orb.Material=Enum.Material.Neon\n        orb.Transparency=.06\n        orb.Color=color\n        local sp=Instance.new(\"Sparkles\")\n        sp.Name=\"AuraSparkles\"\n        sp.SparkleColor=color\n        sp.Parent=orb\n    elseif form.Mode==\"SMOKE\" then\n        orb.Shape=Enum.PartType.Ball\n        orb.Material=Enum.Material.SmoothPlastic\n        orb.Transparency=.52\n        orb.Color=Color3.fromRGB(18,10,28)\n        local sm=Instance.new(\"Smoke\")\n        sm.Name=\"AuraSmoke\"\n        sm.Color=color\n        sm.Opacity=.22\n        sm.RiseVelocity=.7\n        sm.Size=2.3\n        sm.Parent=orb\n    elseif form.Mode==\"ICE\" then\n        orb.Shape=Enum.PartType.Block\n        orb.Material=Enum.Material.Glass\n        orb.Transparency=.12\n        orb.Color=color\n        orb.Reflectance=.08\n    elseif form.Mode==\"BLACKHOLE\" then\n        orb.Shape=Enum.PartType.Ball\n        orb.Material=Enum.Material.SmoothPlastic\n        orb.Transparency=.03\n        orb.Color=Color3.fromRGB(3,3,8)\n        local light=Instance.new(\"PointLight\")\n        light.Color=color\n        light.Brightness=.55\n        light.Range=3.5\n        light.Shadows=false\n        light.Parent=orb\n    else\n        orb.Shape=Enum.PartType.Ball\n        orb.Material=Enum.Material.Neon\n        orb.Transparency=.08+(index%3)*.08\n        orb.Color=color\n        if index%2==0 then\n            local sp=Instance.new(\"Sparkles\")\n            sp.SparkleColor=color\n            sp.Parent=orb\n        end\n    end\nend\n\nlocal function buildAura()\n    destroyAura()\n    if not S.auraReactor then return end\n    local r=root()\n    local c=LP.Character\n    if not r or not c then return end\n    local color=selectedAuraColor()\n    local form=auraForms[S.auraFormIndex] or auraForms[1]\n    AuraLight=Instance.new(\"PointLight\")\n    AuraLight.Name=\"UltraNovaAuraLight\"\n    AuraLight.Color=color\n    AuraLight.Range=9+S.auraIntensity\n    AuraLight.Brightness=.4+S.auraIntensity*.18\n    AuraLight.Shadows=false\n    AuraLight.Parent=r\n    AuraHighlight=Instance.new(\"Highlight\")\n    AuraHighlight.Name=\"UltraNovaAuraHighlight\"\n    AuraHighlight.Adornee=c\n    AuraHighlight.FillColor=color\n    AuraHighlight.OutlineColor=(form.Mode==\"FIRE\" and Color3.fromRGB(255,120,30)) or C.Cyan\n    AuraHighlight.FillTransparency=.91\n    AuraHighlight.OutlineTransparency=.30\n    AuraHighlight.DepthMode=Enum.HighlightDepthMode.Occluded\n    AuraHighlight.Parent=FxFolder\n    for i=1,8 do\n        local orb=Instance.new(\"Part\")\n        orb.Name=\"UltraNovaAuraOrb\"\n        orb.Size=Vector3.new(.26,.26,.26)\n        orb.Anchored=true\n        orb.CanCollide=false\n        orb.CanTouch=false\n        orb.CanQuery=false\n        orb.CastShadow=false\n        decorateAuraPart(orb,form,color,i)\n        orb.Parent=FxFolder\n        table.insert(auraParts,orb)\n    end\n    playAuraPulse(true)\nend\n\nlocal function refreshAuraColor()\n    local color=selectedAuraColor()\n    local form=auraForms[S.auraFormIndex] or auraForms[1]\n    if AuraLight then AuraLight.Color=color end\n    if AuraHighlight then AuraHighlight.FillColor=color end\n    for _,p in ipairs(auraParts) do\n        if p and p.Parent then\n            if form.Mode~=\"BLACKHOLE\" and form.Mode~=\"SMOKE\" then p.Color=color end\n            local fire=p:FindFirstChild(\"AuraFire\")\n            if fire then fire.Color=color end\n            local sp=p:FindFirstChildOfClass(\"Sparkles\")\n            if sp then sp.SparkleColor=color end\n            local sm=p:FindFirstChild(\"AuraSmoke\")\n            if sm then sm.Color=color end\n            local pl=p:FindFirstChildOfClass(\"PointLight\")\n            if pl then pl.Color=color end\n        end\n    end\nend\n\nlocal lastGroundTrace=0\nlocal function tracePart(pos,color,size,material,lifetime)\n    local p=Instance.new(\"Part\")\n    p.Name=\"UltraNovaAuraTrace\"\n    p.Size=size\n    p.CFrame=CFrame.new(pos)\n    p.Anchored=true\n    p.CanCollide=false\n    p.CanTouch=false\n    p.CanQuery=false\n    p.CastShadow=false\n    p.Color=color\n    p.Material=material or Enum.Material.Neon\n    p.Transparency=.18\n    p.Parent=FxFolder\n    TweenService:Create(p,TweenInfo.new(lifetime or 1.4),{Transparency=1,Size=size*1.35}):Play()\n    task.delay((lifetime or 1.4)+.1,function() pcall(function() p:Destroy() end) end)\n    return p\nend\n\nlocal function spawnGroundTrace()\n    if not S.novaTrail or os.clock()-lastGroundTrace<.12 then return end\n    local r=root()\n    local h=humanoid()\n    if not r or not h or h.MoveDirection.Magnitude<.15 then return end\n    local rp=RaycastParams.new()\n    rp.FilterType=Enum.RaycastFilterType.Exclude\n    rp.FilterDescendantsInstances={character(),FxFolder}\n    local hit=workspace:Raycast(r.Position+Vector3.new(0,1,0),Vector3.new(0,-6,0),rp)\n    if not hit then return end\n    lastGroundTrace=os.clock()\n    local form=auraForms[S.auraFormIndex] or auraForms[1]\n    local color=selectedAuraColor()\n    local cf=CFrame.new(hit.Position+hit.Normal*.05)*CFrame.Angles(0,math.rad(math.random(0,360)),0)\n    if form.Mode==\"FIRE\" then\n        local p=tracePart(hit.Position+hit.Normal*.06,Color3.fromRGB(255,90,20),Vector3.new(1.25,.08,1.25),Enum.Material.Neon,1.7)\n        local fire=Instance.new(\"Fire\")\n        fire.Color=color\n        fire.SecondaryColor=Color3.fromRGB(255,40,5)\n        fire.Heat=0\n        fire.Size=2.1\n        fire.Parent=p\n    elseif form.Mode==\"ELECTRIC\" then\n        for i=1,2 do\n            local p=tracePart(hit.Position+hit.Normal*.08,color,Vector3.new(1.35,.045,.12),Enum.Material.Neon,.72)\n            p.CFrame=cf*CFrame.Angles(0,math.rad((i-1)*90),0)\n        end\n    elseif form.Mode==\"SMOKE\" then\n        local anchor=tracePart(hit.Position+hit.Normal*.05,Color3.fromRGB(12,6,20),Vector3.new(.3,.03,.3),Enum.Material.SmoothPlastic,1.8)\n        anchor.Transparency=.82\n        local sm=Instance.new(\"Smoke\")\n        sm.Color=color\n        sm.Opacity=.25\n        sm.RiseVelocity=1.4\n        sm.Size=2.5\n        sm.Parent=anchor\n    elseif form.Mode==\"ICE\" then\n        local p=tracePart(hit.Position+hit.Normal*.22,color,Vector3.new(.34,.65,.34),Enum.Material.Glass,1.9)\n        p.CFrame=cf*CFrame.Angles(math.rad(math.random(-25,25)),0,math.rad(math.random(-25,25)))\n        p.Transparency=.15\n    elseif form.Mode==\"BLACKHOLE\" then\n        local p=tracePart(hit.Position+hit.Normal*.04,Color3.fromRGB(4,4,10),Vector3.new(1.15,.04,1.15),Enum.Material.SmoothPlastic,1.25)\n        local light=Instance.new(\"PointLight\")\n        light.Color=color\n        light.Brightness=.4\n        light.Range=3\n        light.Parent=p\n    else\n        local p=tracePart(hit.Position+hit.Normal*.05,color,Vector3.new(.9,.055,.9),Enum.Material.Neon,1.1)\n        p.CFrame=cf\n        local sp=Instance.new(\"Sparkles\")\n        sp.SparkleColor=color\n        sp.Parent=p\n    end\nend\n\n--========================================================\n-- CINEMATIC MOVEMENT FX\n--========================================================\nlocal function energyRing(position,color,scale)\n    local ring = Instance.new(\"Part\")\n    ring.Name = \"UltraNovaEnergyRing\"\n    ring.Shape = Enum.PartType.Cylinder\n    ring.Size = Vector3.new(.06,1.2,1.2)\n    ring.Anchored = true\n    ring.CanCollide = false\n    ring.CanTouch = false\n    ring.CanQuery = false\n    ring.CastShadow = false\n    ring.Material = Enum.Material.Neon\n    ring.Color = color or C.Cyan\n    ring.Transparency = .22\n    ring.CFrame = CFrame.new(position)*CFrame.Angles(0,0,math.rad(90))\n    ring.Parent = FxFolder\n    TweenService:Create(ring,TweenInfo.new(.34,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{\n        Size=Vector3.new(.03,scale or 8,scale or 8),\n        Transparency=1\n    }):Play()\n    task.delay(.38,function() pcall(function() ring:Destroy() end) end)\nend\n\nlocal lastState = nil\nlocal lastY = nil\nlocal fallStartY = nil\n\nlocal function hookHumanoid(h)\n    if not h then return end\n    h.StateChanged:Connect(function(_,newState)\n        if not alive() then return end\n        lastState = newState\n        local r = root()\n        if not r then return end\n\n        if newState == Enum.HumanoidStateType.Freefall then\n            fallStartY = r.Position.Y\n        elseif newState == Enum.HumanoidStateType.Jumping then\n            if S.cinematicMovementFx then\n                energyRing(r.Position-Vector3.new(0,2.8,0),C.Purple,5.6)\n            end\n        elseif newState == Enum.HumanoidStateType.Landed then\n            if S.cinematicMovementFx then\n                local drop = fallStartY and math.max(0,fallStartY-r.Position.Y) or 0\n                energyRing(r.Position-Vector3.new(0,2.8,0),drop>10 and C.Cyan or C.Purple,math.clamp(6+drop*.18,6,11))\n                if not S.freecam and drop > 8 then\n                    task.spawn(function()\n                        local cam = workspace.CurrentCamera\n                        local start = os.clock()\n                        while alive() and S.cinematicMovementFx and os.clock()-start < .12 do\n                            local amp = (1-(os.clock()-start)/.12)*.07\n                            cam.CFrame = cam.CFrame*CFrame.new(math.sin(os.clock()*115)*amp,math.cos(os.clock()*93)*amp,0)\n                            RunService.RenderStepped:Wait()\n                        end\n                    end)\n                end\n            end\n            fallStartY = nil\n        end\n    end)\nend\n\nhookHumanoid(humanoid())\nLP.CharacterAdded:Connect(function()\n    task.wait(.8)\n    if S.novaTrail then buildTrail() end\n    if S.phaseMode then enablePhase() end\n    if S.auraReactor then buildAura() end\n    hookHumanoid(humanoid())\nend)\n\n--========================================================\n-- CONSTELLATION RADAR\n--========================================================\nlocal Radar = Instance.new(\"Frame\")\nRadar.Name = \"ConstellationRadar\"\nRadar.Size = UDim2.fromOffset(166,166)\nRadar.Position = UDim2.new(1,-182,.5,-83)\nRadar.BackgroundColor3 = C.Space2\nRadar.BackgroundTransparency = .12\nRadar.Visible = false\nRadar.ZIndex = 170\nRadar.Parent = FxGui\ncorner(Radar,18)\nstroke(Radar,C.Purple,1.2,.18)\n\nlocal RadarTitle = Instance.new(\"TextLabel\")\nRadarTitle.Size = UDim2.new(1,-16,0,22)\nRadarTitle.Position = UDim2.fromOffset(8,5)\nRadarTitle.BackgroundTransparency = 1\nRadarTitle.Text = \"✦ CONSTELLATION\"\nRadarTitle.TextColor3 = C.Cyan\nRadarTitle.TextSize = 10\nRadarTitle.Font = Enum.Font.GothamBold\nRadarTitle.ZIndex = 172\nRadarTitle.Parent = Radar\n\nlocal RadarField = Instance.new(\"Frame\")\nRadarField.Size = UDim2.fromOffset(144,128)\nRadarField.Position = UDim2.fromOffset(11,28)\nRadarField.BackgroundTransparency = 1\nRadarField.ZIndex = 171\nRadarField.ClipsDescendants = true\nRadarField.Parent = Radar\n\nlocal CenterDot = Instance.new(\"Frame\")\nCenterDot.Size = UDim2.fromOffset(8,8)\nCenterDot.AnchorPoint = Vector2.new(.5,.5)\nCenterDot.Position = UDim2.fromOffset(72,64)\nCenterDot.BackgroundColor3 = C.White\nCenterDot.ZIndex = 176\nCenterDot.Parent = RadarField\ncorner(CenterDot,8)\n\nfor radius=32,64,32 do\n    local ring = Instance.new(\"Frame\")\n    ring.Size = UDim2.fromOffset(radius*2,radius*2)\n    ring.AnchorPoint = Vector2.new(.5,.5)\n    ring.Position = UDim2.fromOffset(72,64)\n    ring.BackgroundTransparency = 1\n    ring.ZIndex = 171\n    ring.Parent = RadarField\n    corner(ring,999)\n    stroke(ring,C.Purple,1,.72)\nend\n\nlocal RadarDynamic = Instance.new(\"Frame\")\nRadarDynamic.Size = UDim2.fromScale(1,1)\nRadarDynamic.BackgroundTransparency = 1\nRadarDynamic.ZIndex = 173\nRadarDynamic.Parent = RadarField\n\nlocal function uiLine(parent,a,b,color)\n    local delta = b-a\n    local length = delta.Magnitude\n    local line = Instance.new(\"Frame\")\n    line.AnchorPoint = Vector2.new(0,.5)\n    line.Position = UDim2.fromOffset(a.X,a.Y)\n    line.Size = UDim2.fromOffset(length,1)\n    line.Rotation = math.deg(math.atan2(delta.Y,delta.X))\n    line.BackgroundColor3 = color or C.Purple\n    line.BackgroundTransparency = .52\n    line.BorderSizePixel = 0\n    line.ZIndex = 173\n    line.Parent = parent\n    return line\nend\n\nlocal function rebuildRadar()\n    for _,child in ipairs(RadarDynamic:GetChildren()) do child:Destroy() end\n    if not S.constellationRadar then return end\n    local r = root()\n    if not r then return end\n\n    local entries = {}\n    for _,p in ipairs(Players:GetPlayers()) do\n        if p ~= LP then\n            local pr = p.Character and p.Character:FindFirstChild(\"HumanoidRootPart\")\n            if pr then\n                local d = pr.Position-r.Position\n                table.insert(entries,{Player=p,Root=pr,Distance=d.Magnitude,Delta=d})\n            end\n        end\n    end\n    table.sort(entries,function(a,b) return a.Distance<b.Distance end)\n\n    for i=1,math.min(8,#entries) do\n        local e = entries[i]\n        local localVec = r.CFrame:VectorToObjectSpace(e.Delta)\n        local flat = Vector2.new(localVec.X,-localVec.Z)\n        local mag = math.min(flat.Magnitude,250)\n        local dir = flat.Magnitude>0 and flat.Unit or Vector2.new(0,0)\n        local radius = (mag/250)*60\n        local pos = Vector2.new(72,64)+dir*radius\n        local selected = S.selectedPlayer == e.Player\n        local color = selected and C.Cyan or C.Purple\n\n        uiLine(RadarDynamic,Vector2.new(72,64),pos,color)\n\n        local dot = Instance.new(\"TextLabel\")\n        dot.Size = UDim2.fromOffset(selected and 18 or 14,selected and 18 or 14)\n        dot.AnchorPoint = Vector2.new(.5,.5)\n        dot.Position = UDim2.fromOffset(pos.X,pos.Y)\n        dot.BackgroundColor3 = color\n        dot.Text = \"✦\"\n        dot.TextColor3 = C.White\n        dot.TextSize = selected and 10 or 8\n        dot.Font = Enum.Font.GothamBold\n        dot.ZIndex = 175\n        dot.Parent = RadarDynamic\n        corner(dot,12)\n    end\nend\n\ntask.spawn(function()\n    while alive() do\n        if S.constellationRadar then rebuildRadar() end\n        task.wait(.18)\n    end\nend)\n\n--========================================================\n-- LIVE VISUAL UPDATE\n--========================================================\nRunService.RenderStepped:Connect(function()\n    if not alive() then return end\n    Camera = workspace.CurrentCamera or Camera\n    local r = root()\n    local h = humanoid()\n    local speed = r and Vector3.new(r.AssemblyLinearVelocity.X,0,r.AssemblyLinearVelocity.Z).Magnitude or 0\n\n    if S.phaseMode then\n        PhaseBlur.Enabled = true\n        PhaseBlur.Size = math.clamp((speed-18)/12,0,4.5)\n        if PhaseHighlight then\n            local pulse = .5+.5*math.sin(os.clock()*4)\n            PhaseHighlight.OutlineTransparency = .08+.18*pulse\n        end\n    end\n\n    if S.auraReactor and r and #auraParts>0 then\n        local style = auraStyles[S.auraStyleIndex] or auraStyles[1]\n        local t = os.clock()*style.Speed*(S.auraPulseSpeed/4)\n        local radius = S.auraSize*style.Scale\n        for i,p in ipairs(auraParts) do\n            if p and p.Parent then\n                local a = t + (i/#auraParts)*math.pi*2\n                local y = math.sin(a*1.6)*style.Vertical + math.sin(t*2)*.15\n                local wobble = 1 + math.sin(t*S.auraPulseSpeed+i)*.08\n                local pos = r.Position + Vector3.new(math.cos(a)*radius*wobble,y,math.sin(a)*radius*wobble)\n                local s = .18 + S.auraIntensity*.025 + math.sin(t*3+i)*.04\n                local form=auraForms[S.auraFormIndex] or auraForms[1]\n                if form.Mode==\"ICE\" then\n                    p.Size=Vector3.new(s*.72,s*1.9,s*.72)\n                    p.CFrame=CFrame.new(pos)*CFrame.Angles(t*1.7+i,t*2.2+i*.4,t*.9)\n                elseif form.Mode==\"FIRE\" then\n                    p.Size=Vector3.new(s*.75,s*.75,s*.75)\n                    p.CFrame=CFrame.new(pos+Vector3.new(0,math.sin(t*4+i)*.35,0))\n                elseif form.Mode==\"BLACKHOLE\" then\n                    p.Size=Vector3.new(s*1.25,s*1.25,s*1.25)\n                    p.CFrame=CFrame.new(pos)\n                else\n                    p.Size=Vector3.new(s,s,s)\n                    p.CFrame=CFrame.new(pos)\n                end\n            end\n        end\n        if AuraLight then\n            AuraLight.Brightness = .45 + S.auraIntensity*.14 + math.sin(t*S.auraPulseSpeed)*.18\n            AuraLight.Range = 8 + S.auraIntensity + S.auraSize*.35\n        end\n    end\n\n    if S.novaTrail then spawnGroundTrace() end\n\n    if S.cinematicMovementFx or S.phaseMode then\n        if not S.freecam then\n            local base = S.fov or 70\n            local cinematicAdd = S.cinematicMovementFx and math.clamp((speed-12)/5,0,8) or 0\n            local phaseAdd = S.phaseMode and math.clamp((speed-18)/4,0,7) or 0\n            local target = base + cinematicAdd + phaseAdd\n            Camera.FieldOfView = Camera.FieldOfView + (target-Camera.FieldOfView)*.12\n        end\n    end\nend)\n\n--========================================================\n-- UI\n--========================================================\nsection(VisualsPage,\"NOVA FX / AURA\")\n\ntoggle(VisualsPage,\"Nova Trail / Scia cosmica\",false,function(on)\n    S.novaTrail = on\n    if on then buildTrail() else destroyTrail() end\n    feedback(on and C.Cyan or C.PurpleDark)\nend)\n\ntoggle(VisualsPage,\"Phase Mode / Modalità fase\",false,function(on)\n    S.phaseMode = on\n    if on then enablePhase() else disablePhase() end\n    if not on and not S.cinematicMovementFx then\n        Camera.FieldOfView = S.fov or U.original.FOV\n    end\n    feedback(on and C.Purple or C.PurpleDark)\nend)\n\ntoggle(VisualsPage,\"Aura Reactor\",false,function(on)\n    S.auraReactor = on\n    if on then buildAura() else destroyAura() end\n    feedback(on and C.Cyan or C.PurpleDark)\nend)\n\nlocal AuraFormButton\nAuraFormButton = select(1,button(VisualsPage,\"Aura Form: SUPERNOVA\",function(b)\n    S.auraFormIndex=(S.auraFormIndex % #auraForms)+1\n    b.Text=\"Aura Form: \"..auraForms[S.auraFormIndex].Name\n    if S.auraReactor then buildAura() end\n    if S.novaTrail then buildTrail() end\n    playAuraPulse(true)\n    feedback(selectedAuraColor())\nend))\n\nlocal AuraStyleButton\nAuraStyleButton = select(1,button(VisualsPage,\"Orbit Pattern: RING\",function(b)\n    S.auraStyleIndex=(S.auraStyleIndex % #auraStyles)+1\n    b.Text=\"Orbit Pattern: \"..auraStyles[S.auraStyleIndex].Name\n    feedback(C.Purple)\nend))\n\nbutton(VisualsPage,\"Aura Color / Colore aura\",function(b)\n    S.auraColorIndex=(S.auraColorIndex % #auraColors)+1\n    b.TextColor3=auraColors[S.auraColorIndex]\n    refreshAuraColor()\n    if S.novaTrail then buildTrail() end\n    feedback(auraColors[S.auraColorIndex])\nend)\n\ntoggle(VisualsPage,\"Aura Sound / Suono aura\",true,function(on)\n    S.auraSound=on\n    if on then playAuraPulse(true) else AuraSound:Stop() end\nend)\n\nslider(VisualsPage,\"Aura Sound Volume\",0,100,S.auraSoundVolume,function(v)\n    S.auraSoundVolume=v\n    AuraSound.Volume=math.clamp(v/100,0,.65)\nend)\n\nslider(VisualsPage,\"Aura Intensity / Intensità\",1,10,S.auraIntensity,function(v)\n    S.auraIntensity=v\nend)\n\nslider(VisualsPage,\"Aura Size / Dimensione\",2,12,S.auraSize,function(v)\n    S.auraSize=v\nend)\n\nslider(VisualsPage,\"Aura Pulse Speed\",1,10,S.auraPulseSpeed,function(v)\n    S.auraPulseSpeed=v\nend)\n\ntoggle(VisualsPage,\"Cinematic Movement FX\",false,function(on)\n    S.cinematicMovementFx = on\n    if not on and not S.phaseMode then\n        Camera.FieldOfView = S.fov or U.original.FOV\n    end\n    feedback(on and C.Blue or C.PurpleDark)\nend)\n\ntoggle(VisualsPage,\"Constellation Radar\",false,function(on)\n    S.constellationRadar = on\n    Radar.Visible = on\n    if on then rebuildRadar() end\n    feedback(on and C.Cyan or C.PurpleDark)\nend)\n\nU.FxGui = FxGui\nU.FxFolder = FxFolder\nU.rebuildRadar = rebuildRadar\nU.buildAura = buildAura\nU.buildTrail = buildTrail\nU.cleanupAuraFx = function()\n    S.novaTrail=false\n    S.phaseMode=false\n    S.auraReactor=false\n    S.cinematicMovementFx=false\n    S.constellationRadar=false\n    destroyTrail()\n    disablePhase()\n    destroyAura()\n    if AuraSound and AuraSound.Parent then AuraSound:Destroy() end\n    pcall(function() Camera.FieldOfView=S.fov or U.original.FOV end)\n    if PhaseBlur and PhaseBlur.Parent then PhaseBlur:Destroy() end\n    if FxGui and FxGui.Parent then FxGui:Destroy() end\n    if FxFolder and FxFolder.Parent then FxFolder:Destroy() end\nend\n"},
    {"parkour","\nlocal UltraNovaGlobal = (getgenv and getgenv()) or _G\nlocal U = assert(UltraNovaGlobal.UltraNovaV32, \"UltraNova v3.2 core was not loaded\")\n\nlocal Players,RunService,TweenService = U.Players,U.RunService,U.TweenService\nlocal LP = U.LP\nlocal S,C = U.S,U.C\nlocal root,humanoid,character = U.root,U.humanoid,U.character\nlocal makePage,switchPage,heading,infoCard,section,toggle,slider,corner,stroke = U.makePage,U.switchPage,U.heading,U.infoCard,U.section,U.toggle,U.slider,U.corner,U.stroke\n\nS.parkour = S.parkour or false\nS.parkourBusy = false\nS.parkourAutoVault = (S.parkourAutoVault == nil) and true or S.parkourAutoVault\nS.parkourLandingRoll = (S.parkourLandingRoll == nil) and true or S.parkourLandingRoll\nS.parkourTricks = (S.parkourTricks == nil) and true or S.parkourTricks\nS.parkourFx = (S.parkourFx == nil) and true or S.parkourFx\nS.parkourAssistDistance = S.parkourAssistDistance or 4\nS.parkourMaxHeight = S.parkourMaxHeight or 5\nS.parkourSpeed = S.parkourSpeed or 10\n\nlocal gen = UltraNovaGlobal.UltraNovaGeneration or 0\nlocal function alive()\n    return (UltraNovaGlobal.UltraNovaGeneration or 0) == gen and U.Gui and U.Gui.Parent\nend\n\npcall(function()\n    if U.Pages.Parkour then U.Pages.Parkour:Destroy(); U.Pages.Parkour=nil end\n    if U.Navs.Parkour then U.Navs.Parkour:Destroy(); U.Navs.Parkour=nil end\nend)\n\nlocal ParkourPage=makePage(\"Parkour\")\nU.ParkourPage=ParkourPage\n\n-- Force Parkour to the very bottom of the sidebar.\nU.SideList.SortOrder=Enum.SortOrder.LayoutOrder\nlocal Nav=Instance.new(\"TextButton\")\nNav.Name=\"ParkourNav\"\nNav.LayoutOrder=9999\nNav.Size=UDim2.new(1,0,0,42)\nNav.BackgroundColor3=C.Panel\nNav.Text=\"      PARKOUR\"\nNav.TextColor3=C.White\nNav.TextSize=13\nNav.TextXAlignment=Enum.TextXAlignment.Left\nNav.Font=Enum.Font.GothamSemibold\nNav.AutoButtonColor=false\nNav.ZIndex=10\nNav.Parent=U.Sidebar\ncorner(Nav,11)\nstroke(Nav,C.Purple,1,.68)\nU.Navs.Parkour=Nav\n\n-- Stickman landing icon.\nlocal Icon=Instance.new(\"Frame\")\nIcon.Size=UDim2.fromOffset(30,30)\nIcon.Position=UDim2.fromOffset(9,6)\nIcon.BackgroundTransparency=1\nIcon.ZIndex=12\nIcon.Parent=Nav\nlocal Head=Instance.new(\"Frame\")\nHead.Size=UDim2.fromOffset(7,7)\nHead.Position=UDim2.fromOffset(13,1)\nHead.BackgroundColor3=C.Cyan\nHead.ZIndex=13\nHead.Parent=Icon\ncorner(Head,7)\nlocal function limb(x,y,w,h,rot,color)\n    local f=Instance.new(\"Frame\")\n    f.AnchorPoint=Vector2.new(.5,.5)\n    f.Position=UDim2.fromOffset(x,y)\n    f.Size=UDim2.fromOffset(w,h)\n    f.Rotation=rot\n    f.BackgroundColor3=color or C.White\n    f.BorderSizePixel=0\n    f.ZIndex=13\n    f.Parent=Icon\n    corner(f,3)\nend\nlimb(15,13,3,12,12,C.White)\nlimb(10,14,3,11,-52,C.Cyan)\nlimb(20,13,3,12,58,C.Cyan)\nlimb(11,23,3,13,48,C.White)\nlimb(21,22,3,12,-58,C.White)\nNav.MouseButton1Click:Connect(function() switchPage(\"Parkour\") end)\n\nheading(ParkourPage,\"PARKOUR\",\"Custom procedural animation system • Vault • Kong • Flip • Roll\")\ninfoCard(ParkourPage,\"🤸  UltraNova Parkour\",\"Parkour usa pose procedurali vere sul tuo avatar: blocca per un istante le animazioni base, muove braccia/gambe/torso e crea vault contestuali. Il doppio salto NON è più un backflip: resta un boost verticale nella sezione Cheats.\")\n\nlocal parkourCooldown=false\nlocal fallStartY=nil\nlocal lastMove=\"SPEED\"\nlocal vaultCounter=0\n\nlocal function params()\n    local p=RaycastParams.new()\n    p.FilterType=Enum.RaycastFilterType.Exclude\n    p.FilterDescendantsInstances={character()}\n    p.IgnoreWater=false\n    return p\nend\n\nlocal function getMotor(c,...)\n    local names={...}\n    for _,d in ipairs(c:GetDescendants()) do\n        if d:IsA(\"Motor6D\") then\n            for _,n in ipairs(names) do if d.Name==n then return d end end\n        end\n    end\nend\n\nlocal function motorSet()\n    local c=character()\n    return {\n        RS=getMotor(c,\"RightShoulder\",\"Right Shoulder\"),\n        LS=getMotor(c,\"LeftShoulder\",\"Left Shoulder\"),\n        RH=getMotor(c,\"RightHip\",\"Right Hip\"),\n        LH=getMotor(c,\"LeftHip\",\"Left Hip\"),\n        Waist=getMotor(c,\"Waist\",\"RootJoint\",\"Root Joint\"),\n        Neck=getMotor(c,\"Neck\"),\n    }\nend\n\nlocal function beginCustomMotion(h)\n    local pack={Motors=motorSet(),Backup={},AutoRotate=h.AutoRotate}\n    local c=character()\n    pack.Animate=c:FindFirstChild(\"Animate\")\n    if pack.Animate then\n        pack.AnimateDisabled=pack.Animate.Disabled\n        pack.Animate.Disabled=true\n    end\n    pcall(function() for _,tr in ipairs(h:GetPlayingAnimationTracks()) do tr:Stop(.05) end end)\n    for k,m in pairs(pack.Motors) do if m then pack.Backup[k]=m.Transform end end\n    h.AutoRotate=false\n    return pack\nend\n\nlocal function endCustomMotion(h,pack)\n    if not pack then return end\n    for k,m in pairs(pack.Motors) do if m and m.Parent then m.Transform=pack.Backup[k] or CFrame.new() end end\n    if h and h.Parent then h.AutoRotate=pack.AutoRotate end\n    if pack.Animate and pack.Animate.Parent then pack.Animate.Disabled=pack.AnimateDisabled end\nend\n\nlocal function pose(pack,kind,t)\n    local m=pack.Motors\n    local s=math.sin(t*math.pi)\n    local wave=math.sin(t*math.pi*2)\n    if kind==\"SPEED\" then\n        if m.RS then m.RS.Transform=CFrame.Angles(math.rad(-88*s),0,math.rad(25*s)) end\n        if m.LS then m.LS.Transform=CFrame.Angles(math.rad(48*s),0,math.rad(-55*s)) end\n        if m.RH then m.RH.Transform=CFrame.Angles(math.rad(72*s),0,math.rad(-18*s)) end\n        if m.LH then m.LH.Transform=CFrame.Angles(math.rad(-42*s),0,math.rad(22*s)) end\n        if m.Waist then m.Waist.Transform=CFrame.Angles(math.rad(-18*s),0,math.rad(8*wave)) end\n    elseif kind==\"LAZY\" then\n        if m.RS then m.RS.Transform=CFrame.Angles(math.rad(-52*s),0,math.rad(82*s)) end\n        if m.LS then m.LS.Transform=CFrame.Angles(math.rad(-24*s),0,math.rad(-35*s)) end\n        if m.RH then m.RH.Transform=CFrame.Angles(math.rad(30*s),0,math.rad(78*s)) end\n        if m.LH then m.LH.Transform=CFrame.Angles(math.rad(-26*s),0,math.rad(-48*s)) end\n        if m.Waist then m.Waist.Transform=CFrame.Angles(math.rad(-8*s),0,math.rad(-34*s)) end\n    elseif kind==\"KONG\" then\n        if m.RS then m.RS.Transform=CFrame.Angles(math.rad(-122*s),0,math.rad(10*s)) end\n        if m.LS then m.LS.Transform=CFrame.Angles(math.rad(-122*s),0,math.rad(-10*s)) end\n        if m.RH then m.RH.Transform=CFrame.Angles(math.rad(102*s),0,math.rad(12*s)) end\n        if m.LH then m.LH.Transform=CFrame.Angles(math.rad(102*s),0,math.rad(-12*s)) end\n        if m.Waist then m.Waist.Transform=CFrame.Angles(math.rad(-32*s),0,0) end\n    elseif kind==\"BACKFLIP\" then\n        if m.RS then m.RS.Transform=CFrame.Angles(math.rad(-105*s),0,math.rad(22*s)) end\n        if m.LS then m.LS.Transform=CFrame.Angles(math.rad(-105*s),0,math.rad(-22*s)) end\n        if m.RH then m.RH.Transform=CFrame.Angles(math.rad(88*s),0,0) end\n        if m.LH then m.LH.Transform=CFrame.Angles(math.rad(88*s),0,0) end\n        if m.Waist then m.Waist.Transform=CFrame.Angles(math.rad(-35*s),0,0) end\n    elseif kind==\"ROLL\" then\n        if m.RS then m.RS.Transform=CFrame.Angles(math.rad(-72*s),0,math.rad(35*s)) end\n        if m.LS then m.LS.Transform=CFrame.Angles(math.rad(-72*s),0,math.rad(-35*s)) end\n        if m.RH then m.RH.Transform=CFrame.Angles(math.rad(82*s),0,0) end\n        if m.LH then m.LH.Transform=CFrame.Angles(math.rad(82*s),0,0) end\n        if m.Waist then m.Waist.Transform=CFrame.Angles(math.rad(-42*s),0,0) end\n    end\nend\n\nlocal function fxRing(pos,color,size)\n    if not S.parkourFx then return end\n    local ring=Instance.new(\"Part\")\n    ring.Name=\"UltraNovaParkourRing\"\n    ring.Shape=Enum.PartType.Cylinder\n    ring.Size=Vector3.new(.05,1,1)\n    ring.Anchored=true\n    ring.CanCollide=false\n    ring.CanTouch=false\n    ring.CanQuery=false\n    ring.Material=Enum.Material.Neon\n    ring.Color=color or C.Cyan\n    ring.Transparency=.18\n    ring.CFrame=CFrame.new(pos)*CFrame.Angles(0,0,math.rad(90))\n    ring.Parent=workspace\n    TweenService:Create(ring,TweenInfo.new(.28),{Size=Vector3.new(.02,size or 5,size or 5),Transparency=1}):Play()\n    task.delay(.32,function() pcall(function() ring:Destroy() end) end)\nend\n\nlocal function groundYAt(position)\n    local hit=workspace:Raycast(position+Vector3.new(0,7,0),Vector3.new(0,-16,0),params())\n    return hit and hit.Position.Y or nil\nend\n\nlocal function runArc(kind,forward,distance,peak,endY,baseDuration)\n    if S.parkourBusy then return end\n    local r,h=root(),humanoid()\n    if not r or not h then return end\n    S.parkourBusy=true\n    parkourCooldown=true\n    lastMove=kind\n    local anim=beginCustomMotion(h)\n    local startPos=r.Position\n    local finishPos=startPos+forward*distance\n    if endY then finishPos=Vector3.new(finishPos.X,endY,finishPos.Z) end\n    local face=CFrame.lookAt(Vector3.zero,forward)\n    local speedFactor=math.clamp(S.parkourSpeed/10,.6,1.45)\n    local duration=baseDuration/speedFactor\n    local t0=os.clock()\n\n    while alive() and S.parkour and r.Parent and os.clock()-t0<duration do\n        local t=math.clamp((os.clock()-t0)/duration,0,1)\n        local smooth=t*t*(3-2*t)\n        local pos=startPos:Lerp(finishPos,smooth)+Vector3.new(0,4*peak*t*(1-t),0)\n        local rot=CFrame.identity\n        if kind==\"LAZY\" then\n            rot=CFrame.Angles(0,0,math.rad(-22*math.sin(t*math.pi)))\n        elseif kind==\"KONG\" then\n            rot=CFrame.Angles(math.rad(-16*math.sin(t*math.pi)),0,0)\n        elseif kind==\"BACKFLIP\" then\n            rot=CFrame.Angles(math.rad(-360*t),0,0)\n        elseif kind==\"ROLL\" then\n            rot=CFrame.Angles(math.rad(-355*t),0,0)\n        end\n        r.CFrame=CFrame.new(pos)*face*rot\n        r.AssemblyLinearVelocity=Vector3.zero\n        pose(anim,kind,t)\n        RunService.RenderStepped:Wait()\n    end\n\n    endCustomMotion(h,anim)\n    if r and r.Parent then\n        r.AssemblyLinearVelocity=forward*math.max(9,h.WalkSpeed*.62)+Vector3.new(0,2,0)\n    end\n    S.parkourBusy=false\n    task.delay(.34,function() parkourCooldown=false end)\nend\n\nlocal function tryVault()\n    if not S.parkour or not S.parkourAutoVault or S.parkourBusy or parkourCooldown then return end\n    local r,h=root(),humanoid()\n    if not r or not h or h.FloorMaterial==Enum.Material.Air or h.MoveDirection.Magnitude<.18 then return end\n    local forward=h.MoveDirection.Unit\n    local castDistance=math.clamp(S.parkourAssistDistance,2,5.5)\n    local hit=workspace:Raycast(r.Position+Vector3.new(0,.2,0),forward*castDistance,params())\n    if not hit or not hit.Instance or not hit.Instance:IsA(\"BasePart\") or not hit.Instance.CanCollide then return end\n    local model=hit.Instance:FindFirstAncestorOfClass(\"Model\")\n    if model and Players:GetPlayerFromCharacter(model) then return end\n    if math.abs(hit.Normal.Y)>.72 then return end\n\n    local topProbe=workspace:Raycast(hit.Position+forward*.22+Vector3.new(0,7,0),Vector3.new(0,-11,0),params())\n    if not topProbe then return end\n    local footY=r.Position.Y-(h.HipHeight+r.Size.Y*.5)\n    local obstacleHeight=topProbe.Position.Y-footY\n    if obstacleHeight<.75 or obstacleHeight>S.parkourMaxHeight then return end\n    local headClear=workspace:Raycast(r.Position+Vector3.new(0,4.5,0),forward*(castDistance+1.5),params())\n    if headClear and headClear.Instance and headClear.Instance~=hit.Instance then return end\n\n    local distance=math.clamp(castDistance+1.2,4.1,6.3)\n    local landY=groundYAt(r.Position+forward*distance)\n    local endRootY=landY and (landY+h.HipHeight+r.Size.Y*.5) or r.Position.Y\n    vaultCounter+=1\n    local kind\n    if S.parkourTricks and vaultCounter%4==0 and obstacleHeight<3.4 then\n        kind=\"BACKFLIP\"\n    elseif obstacleHeight<1.9 then\n        kind=\"SPEED\"\n    elseif obstacleHeight<3.15 then\n        kind=(lastMove==\"LAZY\") and \"SPEED\" or \"LAZY\"\n    else\n        kind=\"KONG\"\n    end\n    local peak=math.clamp(obstacleHeight*.58+1.1,1.7,3.8)\n    local duration=(kind==\"KONG\" and .62) or (kind==\"BACKFLIP\" and .68) or .50\n    fxRing(r.Position-Vector3.new(0,h.HipHeight+r.Size.Y*.5,0),kind==\"BACKFLIP\" and C.Purple or C.Cyan,5.2)\n    task.spawn(runArc,kind,forward,distance,peak,endRootY,duration)\nend\n\nRunService.Heartbeat:Connect(function()\n    if alive() and S.parkour then tryVault() end\nend)\n\nlocal function hookHumanoid(h)\n    if not h then return end\n    h.StateChanged:Connect(function(_,state)\n        if not alive() or not S.parkour then return end\n        local r=root()\n        if not r then return end\n        if state==Enum.HumanoidStateType.Freefall then\n            if not fallStartY then fallStartY=r.Position.Y end\n        elseif state==Enum.HumanoidStateType.Landed then\n            local drop=fallStartY and (fallStartY-r.Position.Y) or 0\n            fallStartY=nil\n            if S.parkourLandingRoll and drop>9 and not S.parkourBusy and not parkourCooldown then\n                local dir\n                if h.MoveDirection.Magnitude>.1 then dir=h.MoveDirection.Unit\n                else\n                    local flat=Vector3.new(r.CFrame.LookVector.X,0,r.CFrame.LookVector.Z)\n                    dir=flat.Magnitude>.05 and flat.Unit or Vector3.new(0,0,-1)\n                end\n                fxRing(r.Position-Vector3.new(0,h.HipHeight+r.Size.Y*.5,0),C.Cyan,6)\n                task.spawn(runArc,\"ROLL\",dir,3.2,.65,r.Position.Y,.46)\n            end\n        end\n    end)\nend\nhookHumanoid(humanoid())\nLP.CharacterAdded:Connect(function()\n    fallStartY=nil\n    S.parkourBusy=false\n    parkourCooldown=false\n    task.wait(.8)\n    hookHumanoid(humanoid())\nend)\n\ntoggle(ParkourPage,\"Parkour\",false,function(on)\n    S.parkour=on\n    S.parkourBusy=false\n    if not on then fallStartY=nil end\n    local icon=U.NovaIcon\n    if icon and icon.Parent then\n        local old=icon.BackgroundColor3\n        TweenService:Create(icon,TweenInfo.new(.1),{Rotation=18,BackgroundColor3=on and C.Cyan or C.PurpleDark}):Play()\n        task.delay(.12,function() if icon and icon.Parent then TweenService:Create(icon,TweenInfo.new(.2,Enum.EasingStyle.Back),{Rotation=0,BackgroundColor3=old}):Play() end end)\n    end\nend)\n\nsection(ParkourPage,\"IMPOSTAZIONI PARKOUR / PARKOUR SETTINGS\")\ntoggle(ParkourPage,\"Auto Vault\",true,function(on) S.parkourAutoVault=on end)\ntoggle(ParkourPage,\"Landing Roll\",true,function(on) S.parkourLandingRoll=on end)\ntoggle(ParkourPage,\"Trick Vaults / Backflip contestuali\",true,function(on) S.parkourTricks=on end)\ntoggle(ParkourPage,\"Parkour FX\",true,function(on) S.parkourFx=on end)\nslider(ParkourPage,\"Distanza assist / Assist Distance\",2,5,S.parkourAssistDistance,function(v) S.parkourAssistDistance=v end)\nslider(ParkourPage,\"Altezza max ostacolo / Max Height\",2,6,S.parkourMaxHeight,function(v) S.parkourMaxHeight=v end)\nslider(ParkourPage,\"Velocità animazioni / Animation Speed\",6,14,S.parkourSpeed,function(v) S.parkourSpeed=v end)\n\nU.ParkourNav=Nav\nU.cleanupParkour=function()\n    S.parkour=false\n    S.parkourBusy=false\nend\n"},
    {"server_tools","local UltraNovaGlobal = (getgenv and getgenv()) or _G\nlocal U = assert(UltraNovaGlobal.UltraNovaV32, \"UltraNova v3.2 core was not loaded\")\nlocal Players,UIS,RunService,TweenService,Lighting,SoundService,TeleportService,MarketplaceService,GuiService,VirtualUser,CoreGui,HttpService,Stats,ContentProvider,StarterGui = U.Players,U.UIS,U.RunService,U.TweenService,U.Lighting,U.SoundService,U.TeleportService,U.MarketplaceService,U.GuiService,U.VirtualUser,U.CoreGui,U.HttpService,U.Stats,U.ContentProvider,U.StarterGui\nlocal LP,Camera,unpackArgs = U.LP,U.Camera,U.unpackArgs\nlocal character,humanoid,root = U.character,U.humanoid,U.root\nlocal GuiParent,C,ESP_PALETTE = U.GuiParent,U.C,U.ESP_PALETTE\nlocal corner,stroke,gradient,padding = U.corner,U.stroke,U.gradient,U.padding\nlocal S,original = U.S,U.original\nlocal Gui,Main,Scale,refreshScale,Stars = U.Gui,U.Main,U.Scale,U.refreshScale,U.Stars\nlocal MainLineFX,restartMainLineTweens = U.MainLineFX,U.restartMainLineTweens\nlocal Header,NovaIcon,Title,SubTitle,Minimize,Mini,MiniLineFX,restartMiniLineTweens = U.Header,U.NovaIcon,U.Title,U.SubTitle,U.Minimize,U.Mini,U.MiniLineFX,U.restartMiniLineTweens\nlocal toast = U.toast\nlocal MenuAmbience,MenuWhoosh,syncMenuAudio = U.MenuAmbience,U.MenuWhoosh,U.syncMenuAudio\nlocal Sidebar,SideList,Content,Pages,Navs = U.Sidebar,U.SideList,U.Content,U.Pages,U.Navs\nlocal makePage,switchPage = U.makePage,U.switchPage\nlocal Home,Cheats,PlayersPage,CameraPage,VisualsPage,Emotes,Shaders,ServerPage,PerformancePage,ToolsPage,SettingsPage = U.Home,U.Cheats,U.PlayersPage,U.CameraPage,U.VisualsPage,U.Emotes,U.Shaders,U.ServerPage,U.PerformancePage,U.ToolsPage,U.SettingsPage\nlocal ControlRegistry,registerControl = U.ControlRegistry,U.registerControl\nlocal heading,section,card,infoCard,button,toggle,slider = U.heading,U.section,U.card,U.infoCard,U.button,U.toggle,U.slider\nlocal ModalDim,playerPicker = U.ModalDim,U.playerPicker\n\n--========================================================\n-- SERVER PAGE\n--========================================================\nheading(ServerPage,\"SERVER\",\"Server tools • Hop • Small server • Live stats\")\nlocal ServerStatsCard,ServerStatsText=infoCard(ServerPage,\"⌁ Server Status\",\"\")\ntask.spawn(function()\n    while Gui.Parent do\n        ServerStatsText.Text=\"Players: \"..#Players:GetPlayers()..\" / \"..Players.MaxPlayers..\"\\nPing: \"..pingText()..\" • FPS: \"..RuntimeFPS..\"\\nSession: \"..uptimeText()..\"\\nJobId: \"..string.sub(game.JobId,1,18)..\"...\"\n        task.wait(.5)\n    end\nend)\n\nlocal function fetchServers(sortOrder)\n    local url=\"https://games.roblox.com/v1/games/\"..game.PlaceId..\"/servers/Public?sortOrder=\"..(sortOrder or \"Asc\")..\"&limit=100\"\n    local body=game:HttpGet(url)\n    return HttpService:JSONDecode(body).data or {}\nend\n\nlocal function hopServer(mode)\n    toast(\"Cerco server / Searching...\",C.Cyan)\n    task.spawn(function()\n        local ok,servers=pcall(fetchServers,mode==\"random\" and \"Desc\" or \"Asc\")\n        if not ok then toast(\"Server list unavailable\",C.Red) return end\n        local candidates={}\n        for _,s in ipairs(servers) do if s.id~=game.JobId and s.playing<s.maxPlayers then table.insert(candidates,s) end end\n        if #candidates==0 then toast(\"Nessun server trovato / No server found\",C.Orange) return end\n        local target\n        if mode==\"random\" then target=candidates[math.random(1,#candidates)] else table.sort(candidates,function(a,b) return a.playing<b.playing end); target=candidates[1] end\n        pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId,target.id,LP) end)\n    end)\nend\n\nbutton(ServerPage,\"⟳ Rejoin\",function() TeleportService:Teleport(game.PlaceId,LP) end)\nbutton(ServerPage,\"⇄ Server Hop\",function() hopServer(\"random\") end)\nbutton(ServerPage,\"⇣ Join Smallest Server\",function() hopServer(\"small\") end)\nbutton(ServerPage,\"Copia JobId / Copy JobId\",function() if setclipboard then setclipboard(game.JobId) else toast(game.JobId,C.Cyan) end end)\nbutton(ServerPage,\"Copia PlaceId / Copy PlaceId\",function() if setclipboard then setclipboard(tostring(game.PlaceId)) else toast(tostring(game.PlaceId),C.Cyan) end end)\n\n--========================================================\n-- PERFORMANCE PAGE\n--========================================================\nheading(PerformancePage,\"PERFORMANCE\",\"FPS • Ping • Low Graphics • Restore\")\nlocal PerfCard,PerfText=infoCard(PerformancePage,\"⚡ Live Performance\",\"\")\ntask.spawn(function()\n    while Gui.Parent do PerfText.Text=\"FPS: \"..RuntimeFPS..\"\\nPing: \"..pingText()..\"\\nMemory: \"..memoryText()..\"\\nSession: \"..uptimeText(); task.wait(.5) end\nend)\n\nlocal FpsCaps={30,45,60,90,120,144,240}; local FpsCapIndex=3\nbutton(PerformancePage,\"FPS Cap: 60\",function(b)\n    FpsCapIndex=FpsCapIndex%#FpsCaps+1; local cap=FpsCaps[FpsCapIndex]; b.Text=\"FPS Cap: \"..cap\n    if setfpscap then pcall(function() setfpscap(cap) end) else toast(\"setfpscap unsupported\",C.Orange) end\nend)\n\nlocal PerfBackup={}\nlocal ParticleBackup={}\nlocal function backupPart(p) if not PerfBackup[p] then PerfBackup[p]={Material=p.Material,Reflectance=p.Reflectance,CastShadow=p.CastShadow} end end\n\nbutton(PerformancePage,\"Low Graphics\",function()\n    task.spawn(function()\n        local n=0\n        for _,d in ipairs(workspace:GetDescendants()) do\n            if d:IsA(\"BasePart\") and not d:IsDescendantOf(character()) then\n                backupPart(d); d.Material=Enum.Material.SmoothPlastic; d.Reflectance=0; d.CastShadow=false; n+=1\n                if n%350==0 then task.wait() end\n            end\n        end\n        Lighting.GlobalShadows=false; toast(\"Low Graphics ON\",C.Green)\n    end)\nend)\n\nbutton(PerformancePage,\"Disable Particles\",function()\n    for _,d in ipairs(workspace:GetDescendants()) do\n        if d:IsA(\"ParticleEmitter\") or d:IsA(\"Trail\") or d:IsA(\"Smoke\") or d:IsA(\"Fire\") or d:IsA(\"Sparkles\") then if ParticleBackup[d]==nil then ParticleBackup[d]=d.Enabled end; d.Enabled=false end\n    end\n    toast(\"Particles OFF\",C.Green)\nend)\n\nbutton(PerformancePage,\"Disable Shadows\",function() Lighting.GlobalShadows=false; for _,d in ipairs(workspace:GetDescendants()) do if d:IsA(\"BasePart\") then backupPart(d); d.CastShadow=false end end end)\n\nbutton(PerformancePage,\"POTATO MODE\",function()\n    Lighting.GlobalShadows=false\n    task.spawn(function()\n        local n=0\n        for _,d in ipairs(workspace:GetDescendants()) do\n            if d:IsA(\"BasePart\") and not d:IsDescendantOf(character()) then\n                backupPart(d); d.Material=Enum.Material.SmoothPlastic; d.Reflectance=0; d.CastShadow=false; n+=1\n                if n%400==0 then task.wait() end\n            end\n            if d:IsA(\"ParticleEmitter\") or d:IsA(\"Trail\") or d:IsA(\"Smoke\") or d:IsA(\"Fire\") or d:IsA(\"Sparkles\") then if ParticleBackup[d]==nil then ParticleBackup[d]=d.Enabled end; d.Enabled=false end\n        end\n        toast(\"POTATO MODE 🥔\",C.Orange)\n    end)\nend)\n\nbutton(PerformancePage,\"Restore Graphics\",function()\n    for p,v in pairs(PerfBackup) do if p and p.Parent then p.Material=v.Material; p.Reflectance=v.Reflectance; p.CastShadow=v.CastShadow end end; PerfBackup={}\n    for d,v in pairs(ParticleBackup) do if d and d.Parent then d.Enabled=v end end; ParticleBackup={}\n    Lighting.GlobalShadows=original.GlobalShadows\n    toast(\"Graphics restored\",C.Cyan)\nend)\n\n--========================================================\n-- TOOLS PAGE\n--========================================================\nheading(ToolsPage,\"TOOLS\",\"Coordinates • Waypoints • Clipboard • Session\")\nlocal CoordCard,CoordText=infoCard(ToolsPage,\"＋ Coordinates\",\"\")\nlocal CoordHudEnabled=false\nlocal CoordHud=Instance.new(\"TextLabel\"); CoordHud.Size=UDim2.fromOffset(250,30); CoordHud.Position=UDim2.new(.5,-125,0,10); CoordHud.BackgroundColor3=C.Space2; CoordHud.BackgroundTransparency=.25; CoordHud.TextColor3=C.Cyan; CoordHud.Font=Enum.Font.GothamBold; CoordHud.TextSize=11; CoordHud.Visible=false; CoordHud.ZIndex=75; CoordHud.Parent=Gui; corner(CoordHud,10)\n\ntask.spawn(function()\n    while Gui.Parent do\n        local r=root(); local txt=\"Position unavailable\"\n        if r then txt=string.format(\"X %.1f   Y %.1f   Z %.1f\",r.Position.X,r.Position.Y,r.Position.Z) end\n        CoordText.Text=txt..\"\\nSession: \"..uptimeText(); CoordHud.Text=txt; CoordHud.Visible=CoordHudEnabled; task.wait(.15)\n    end\nend)\n\ntoggle(ToolsPage,\"Coordinates HUD\",false,function(on) CoordHudEnabled=on end)\nbutton(ToolsPage,\"Copia posizione / Copy Position\",function()\n    local r=root(); if not r then return end; local txt=string.format(\"%.3f, %.3f, %.3f\",r.Position.X,r.Position.Y,r.Position.Z); if setclipboard then setclipboard(txt) else toast(txt,C.Cyan) end\nend)\nbutton(ToolsPage,\"Copia CFrame / Copy CFrame\",function()\n    local r=root(); if not r then return end; local c={r.CFrame:GetComponents()}; local out=\"CFrame.new(\"..table.concat(c,\", \")..\")\"; if setclipboard then setclipboard(out) else toast(\"CFrame ready\",C.Cyan) end\nend)\nbutton(ToolsPage,\"Copia timestamp / Copy Timestamp\",function()\n    local t=os.date(\"!%Y-%m-%dT%H:%M:%SZ\"); if setclipboard then setclipboard(t) else toast(t,C.Cyan) end\nend)\n\nlocal Waypoints={}\nfor i=1,5 do\n    button(ToolsPage,\"Save Waypoint \"..i,function()\n        local r=root(); if r then Waypoints[i]=r.CFrame; toast(\"Waypoint \"..i..\" saved\",C.Green) end\n    end)\n    button(ToolsPage,\"Go Waypoint \"..i,function()\n        local r=root(); if r and Waypoints[i] then r.CFrame=Waypoints[i] else toast(\"Waypoint \"..i..\" empty\",C.Orange) end\n    end)\nend\n\n\n\nU.CoordHud = CoordHud\n"},
    {"settings","local UltraNovaGlobal = (getgenv and getgenv()) or _G\nlocal U = assert(UltraNovaGlobal.UltraNovaV32, \"UltraNova v3.2 core was not loaded\")\nlocal Players,UIS,RunService,TweenService,Lighting,SoundService,TeleportService,MarketplaceService,GuiService,VirtualUser,CoreGui,HttpService,Stats,ContentProvider,StarterGui = U.Players,U.UIS,U.RunService,U.TweenService,U.Lighting,U.SoundService,U.TeleportService,U.MarketplaceService,U.GuiService,U.VirtualUser,U.CoreGui,U.HttpService,U.Stats,U.ContentProvider,U.StarterGui\nlocal LP,Camera,unpackArgs = U.LP,U.Camera,U.unpackArgs\nlocal character,humanoid,root = U.character,U.humanoid,U.root\nlocal GuiParent,C,ESP_PALETTE = U.GuiParent,U.C,U.ESP_PALETTE\nlocal corner,stroke,gradient,padding = U.corner,U.stroke,U.gradient,U.padding\nlocal S,original = U.S,U.original\nlocal Gui,Main,Scale,refreshScale,Stars = U.Gui,U.Main,U.Scale,U.refreshScale,U.Stars\nlocal MainLineFX,restartMainLineTweens = U.MainLineFX,U.restartMainLineTweens\nlocal Header,NovaIcon,Title,SubTitle,Minimize,Mini,MiniLineFX,restartMiniLineTweens = U.Header,U.NovaIcon,U.Title,U.SubTitle,U.Minimize,U.Mini,U.MiniLineFX,U.restartMiniLineTweens\nlocal toast = U.toast\nlocal MenuAmbience,MenuWhoosh,syncMenuAudio = U.MenuAmbience,U.MenuWhoosh,U.syncMenuAudio\nlocal Sidebar,SideList,Content,Pages,Navs = U.Sidebar,U.SideList,U.Content,U.Pages,U.Navs\nlocal makePage,switchPage = U.makePage,U.switchPage\nlocal Home,Cheats,PlayersPage,CameraPage,VisualsPage,Emotes,Shaders,ServerPage,PerformancePage,ToolsPage,SettingsPage = U.Home,U.Cheats,U.PlayersPage,U.CameraPage,U.VisualsPage,U.Emotes,U.Shaders,U.ServerPage,U.PerformancePage,U.ToolsPage,U.SettingsPage\nlocal ControlRegistry,registerControl = U.ControlRegistry,U.registerControl\nlocal heading,section,card,infoCard,button,toggle,slider = U.heading,U.section,U.card,U.infoCard,U.button,U.toggle,U.slider\nlocal ModalDim,playerPicker = U.ModalDim,U.playerPicker\n\nlocal ShaderPresets,applyShaderPreset = U.ShaderPresets,U.applyShaderPreset\nlocal refreshEsp = U.refreshEsp\nlocal FlyPad = U.FlyPad\n\n--========================================================\n-- SETTINGS PAGE\n--========================================================\nheading(SettingsPage,\"SETTINGS\",\"Themes • UI • Motion • Language • Profiles\")\n\nlocal ThemeOrder={\"Purple\",\"Blue\",\"Cyan\",\"Red\",\"AMOLED\"}; local ThemeIndex=1\nlocal Themes={\n    Purple={Space=Color3.fromRGB(7,5,17),Space2=Color3.fromRGB(13,8,30),Panel=Color3.fromRGB(20,14,43),Panel2=Color3.fromRGB(29,19,60),Purple=Color3.fromRGB(151,77,255),PurpleDark=Color3.fromRGB(97,46,191),Cyan=Color3.fromRGB(93,220,255),Blue=Color3.fromRGB(62,148,255)},\n    Blue={Space=Color3.fromRGB(4,8,18),Space2=Color3.fromRGB(7,16,34),Panel=Color3.fromRGB(12,25,48),Panel2=Color3.fromRGB(18,36,67),Purple=Color3.fromRGB(69,130,255),PurpleDark=Color3.fromRGB(37,82,190),Cyan=Color3.fromRGB(92,226,255),Blue=Color3.fromRGB(55,145,255)},\n    Cyan={Space=Color3.fromRGB(3,12,15),Space2=Color3.fromRGB(5,24,29),Panel=Color3.fromRGB(9,37,42),Panel2=Color3.fromRGB(12,51,58),Purple=Color3.fromRGB(45,230,236),PurpleDark=Color3.fromRGB(20,145,157),Cyan=Color3.fromRGB(155,255,255),Blue=Color3.fromRGB(45,175,225)},\n    Red={Space=Color3.fromRGB(17,5,8),Space2=Color3.fromRGB(32,8,13),Panel=Color3.fromRGB(48,14,20),Panel2=Color3.fromRGB(66,20,29),Purple=Color3.fromRGB(255,72,92),PurpleDark=Color3.fromRGB(182,38,57),Cyan=Color3.fromRGB(255,173,184),Blue=Color3.fromRGB(226,71,115)},\n    AMOLED={Space=Color3.fromRGB(0,0,0),Space2=Color3.fromRGB(2,2,4),Panel=Color3.fromRGB(8,8,12),Panel2=Color3.fromRGB(15,15,22),Purple=Color3.fromRGB(157,82,255),PurpleDark=Color3.fromRGB(90,42,170),Cyan=Color3.fromRGB(100,220,255),Blue=Color3.fromRGB(62,148,255)}\n}\n\nlocal function applyTheme(name)\n    local t=Themes[name]; if not t then return end\n    local old={Space=C.Space,Space2=C.Space2,Panel=C.Panel,Panel2=C.Panel2,Purple=C.Purple,PurpleDark=C.PurpleDark,Cyan=C.Cyan,Blue=C.Blue}\n    for k,v in pairs(t) do C[k]=v end\n    S.themeName=name\n    for _,d in ipairs(Gui:GetDescendants()) do\n        if d:IsA(\"GuiObject\") then\n            for k,ov in pairs(old) do if d.BackgroundColor3==ov and t[k] then d.BackgroundColor3=t[k] end end\n            if d:IsA(\"TextLabel\") or d:IsA(\"TextButton\") or d:IsA(\"TextBox\") then if d.TextColor3==old.Cyan then d.TextColor3=C.Cyan elseif d.TextColor3==old.Purple then d.TextColor3=C.Purple end end\n        elseif d:IsA(\"UIStroke\") then\n            if d.Color==old.Purple then d.Color=C.Purple elseif d.Color==old.Cyan then d.Color=C.Cyan elseif d.Color==old.Blue then d.Color=C.Blue end\n        end\n    end\n    toast(\"Theme: \"..name,C.Cyan)\nend\n\nbutton(SettingsPage,\"Theme: PURPLE\",function(b)\n    ThemeIndex=ThemeIndex%#ThemeOrder+1; local name=ThemeOrder[ThemeIndex]; b.Text=\"Theme: \"..string.upper(name); applyTheme(name)\nend)\n\nslider(SettingsPage,\"Velocità linee / Line Speed %\",40,220,100,function(v)\n    S.lineSpeed=v/100; restartMainLineTweens(); restartMiniLineTweens()\nend)\n\ntoggle(SettingsPage,\"Line FX\",true,function(on)\n    S.lineFx=on; restartMainLineTweens(); restartMiniLineTweens()\nend)\n\ntoggle(SettingsPage,\"Reduce Motion\",false,function(on)\n    S.reduceMotion=on; Stars.Visible=not on; restartMainLineTweens(); restartMiniLineTweens()\nend)\n\nslider(SettingsPage,\"Dimensione GUI / GUI Size %\",70,130,100,function(v)\n    S.guiScale=v/100; refreshScale()\nend)\n\nslider(SettingsPage,\"Trasparenza GUI / GUI Transparency\",0,65,0,function(v)\n    S.guiTransparency=v/100\n    for _,d in ipairs(Gui:GetDescendants()) do\n        if d:IsA(\"Frame\") or d:IsA(\"TextButton\") or d:IsA(\"ScrollingFrame\") then\n            if d:GetAttribute(\"UltraNovaBaseTransparency\")==nil then d:SetAttribute(\"UltraNovaBaseTransparency\",d.BackgroundTransparency) end\n            local base=d:GetAttribute(\"UltraNovaBaseTransparency\") or 0\n            if d.BackgroundTransparency<1 then d.BackgroundTransparency=math.clamp(base+S.guiTransparency*.55,0,.9) end\n        end\n    end\nend)\n\nslider(SettingsPage,\"Dimensione mini button / Mini Size %\",75,140,100,function(v)\n    local s=v/100; Mini.Size=UDim2.fromOffset(112*s,40*s)\nend)\n\nlocal function snapshotOriginalTexts()\n    for _,d in ipairs(Gui:GetDescendants()) do\n        if (d:IsA(\"TextLabel\") or d:IsA(\"TextButton\")) and d:GetAttribute(\"UltraNovaOriginalText\")==nil then d:SetAttribute(\"UltraNovaOriginalText\",d.Text) end\n    end\nend\n\nlocal function applyLanguageMode(mode)\n    snapshotOriginalTexts(); S.languageMode=mode\n    for _,d in ipairs(Gui:GetDescendants()) do\n        if d:IsA(\"TextLabel\") or d:IsA(\"TextButton\") then\n            local originalText=d:GetAttribute(\"UltraNovaOriginalText\")\n            if originalText then\n                if mode==\"Bilingual\" then d.Text=originalText\n                else\n                    local a,b=string.match(originalText,\"^(.-)%s/%s(.-)$\")\n                    if a and b then d.Text=(mode==\"IT\") and a or b else d.Text=originalText end\n                end\n            end\n        end\n    end\nend\n\nlocal LanguageIndex=1; local Languages={\"Bilingual\",\"IT\",\"EN\"}\nbutton(SettingsPage,\"Lingua / Language: IT+EN\",function(b)\n    LanguageIndex=LanguageIndex%#Languages+1; local mode=Languages[LanguageIndex]; applyLanguageMode(mode); b.Text=\"Language: \"..mode\nend)\n\nslider(SettingsPage,\"Volume Menu Ambience\",0,30,11,function(v) S.menuMusicVolume=v/100; syncMenuAudio() end)\n\nsection(SettingsPage,\"PROFILES\")\nbutton(SettingsPage,\"Profile: Default\",function()\n    S.speed=16; S.jump=50; S.gravity=196.2; S.flySpeed=55; workspace.Gravity=S.gravity; Camera.FieldOfView=70; applyTheme(\"Purple\"); toast(\"Default profile\",C.Cyan)\nend)\nbutton(SettingsPage,\"Profile: Performance\",function()\n    S.speed=22; S.jump=55; Lighting.GlobalShadows=false; S.reduceMotion=true; Stars.Visible=false; restartMainLineTweens(); restartMiniLineTweens(); toast(\"Performance profile\",C.Green)\nend)\nbutton(SettingsPage,\"Profile: Visual\",function()\n    for _,p in ipairs(ShaderPresets) do if p.Name==\"Deep Space\" then applyShaderPreset(p) break end end; S.esp=true; refreshEsp(); toast(\"Visual profile\",C.Purple)\nend)\nbutton(SettingsPage,\"Profile: Movement\",function()\n    S.speed=32; S.jump=80; S.gravity=145; S.flySpeed=90; workspace.Gravity=S.gravity; toast(\"Movement profile\",C.Cyan)\nend)\n\nlocal SETTINGS_FILE=\"UltraNova_v3_2_settings.json\"\nbutton(SettingsPage,\"Save Custom Settings\",function()\n    if not writefile then toast(\"writefile unsupported\",C.Orange) return end\n    local data={speed=S.speed,jump=S.jump,gravity=S.gravity,flySpeed=S.flySpeed,fov=S.fov,guiScale=S.guiScale,lineSpeed=S.lineSpeed,theme=S.themeName,menuMusic=S.menuMusic,menuVolume=S.menuMusicVolume}\n    local ok=pcall(function() writefile(SETTINGS_FILE,HttpService:JSONEncode(data)) end); toast(ok and \"Settings saved\" or \"Save failed\",ok and C.Green or C.Red)\nend)\nbutton(SettingsPage,\"Load Custom Settings\",function()\n    if not readfile or (isfile and not isfile(SETTINGS_FILE)) then toast(\"No saved settings\",C.Orange) return end\n    local ok,data=pcall(function() return HttpService:JSONDecode(readfile(SETTINGS_FILE)) end)\n    if ok and data then S.speed=data.speed or S.speed; S.jump=data.jump or S.jump; S.gravity=data.gravity or S.gravity; S.flySpeed=data.flySpeed or S.flySpeed; S.fov=data.fov or S.fov; S.guiScale=data.guiScale or S.guiScale; S.lineSpeed=data.lineSpeed or S.lineSpeed; S.menuMusic=(data.menuMusic~=false); S.menuMusicVolume=data.menuVolume or S.menuMusicVolume; workspace.Gravity=S.gravity; Camera.FieldOfView=S.fov; if data.theme then applyTheme(data.theme) end; refreshScale(); restartMainLineTweens(); restartMiniLineTweens(); syncMenuAudio(); toast(\"Settings loaded\",C.Green) else toast(\"Load failed\",C.Red) end\nend)\n\n--========================================================\n-- COMMAND PALETTE / SEARCH\n--========================================================\nlocal SearchButton=Instance.new(\"TextButton\")\nSearchButton.Size=UDim2.fromOffset(40,34); SearchButton.Position=UDim2.new(1,-94,.5,-17); SearchButton.BackgroundColor3=C.Panel2; SearchButton.Text=\"⌕\"; SearchButton.TextColor3=C.White; SearchButton.TextSize=18; SearchButton.Font=Enum.Font.GothamBold; SearchButton.ZIndex=11; SearchButton.Parent=Header; corner(SearchButton,10)\n\nlocal SearchOverlay=Instance.new(\"Frame\")\nSearchOverlay.Size=UDim2.fromOffset(390,360); SearchOverlay.Position=UDim2.fromScale(.5,.5); SearchOverlay.AnchorPoint=Vector2.new(.5,.5); SearchOverlay.BackgroundColor3=C.Space2; SearchOverlay.Visible=false; SearchOverlay.ZIndex=160; SearchOverlay.Parent=Gui; corner(SearchOverlay,16); stroke(SearchOverlay,C.Purple,1.4,.08)\nlocal SearchBox=Instance.new(\"TextBox\"); SearchBox.Size=UDim2.new(1,-60,0,42); SearchBox.Position=UDim2.fromOffset(10,10); SearchBox.BackgroundColor3=C.Panel; SearchBox.PlaceholderText=\"Search UltraNova...\"; SearchBox.Text=\"\"; SearchBox.TextColor3=C.White; SearchBox.PlaceholderColor3=C.Soft; SearchBox.Font=Enum.Font.Gotham; SearchBox.TextSize=13; SearchBox.ClearTextOnFocus=false; SearchBox.ZIndex=161; SearchBox.Parent=SearchOverlay; corner(SearchBox,10)\nlocal SearchClose=Instance.new(\"TextButton\"); SearchClose.Size=UDim2.fromOffset(38,38); SearchClose.Position=UDim2.new(1,-48,0,12); SearchClose.BackgroundColor3=C.Panel2; SearchClose.Text=\"×\"; SearchClose.TextColor3=C.White; SearchClose.ZIndex=161; SearchClose.Parent=SearchOverlay; corner(SearchClose,10)\nlocal SearchResults=Instance.new(\"ScrollingFrame\"); SearchResults.Size=UDim2.new(1,-20,1,-70); SearchResults.Position=UDim2.fromOffset(10,60); SearchResults.BackgroundTransparency=1; SearchResults.BorderSizePixel=0; SearchResults.AutomaticCanvasSize=Enum.AutomaticSize.Y; SearchResults.CanvasSize=UDim2.fromOffset(0,0); SearchResults.ScrollBarThickness=3; SearchResults.ZIndex=161; SearchResults.Parent=SearchOverlay; local SRList=Instance.new(\"UIListLayout\"); SRList.Padding=UDim.new(0,6); SRList.Parent=SearchResults\n\nlocal function refreshSearch()\n    for _,d in ipairs(SearchResults:GetChildren()) do if d:IsA(\"TextButton\") then d:Destroy() end end\n    local q=string.lower(SearchBox.Text or \"\"); if #q<1 then return end\n    local shown=0\n    for _,entry in ipairs(ControlRegistry) do\n        if string.find(string.lower(entry.Text),q,1,true) then\n            shown+=1; if shown>25 then break end\n            local b=Instance.new(\"TextButton\"); b.Size=UDim2.new(1,-5,0,38); b.BackgroundColor3=C.Panel; b.Text=entry.Page..\"  •  \"..entry.Text; b.TextColor3=C.White; b.TextSize=11; b.TextXAlignment=Enum.TextXAlignment.Left; b.Font=Enum.Font.Gotham; b.ZIndex=162; b.Parent=SearchResults; corner(b,9)\n            b.MouseButton1Click:Connect(function()\n                SearchOverlay.Visible=false; Main.Visible=true; Mini.Visible=false; switchPage(entry.Page)\n                local page=Pages[entry.Page]\n                if page and entry.Frame and entry.Frame.Parent==page then page.CanvasPosition=Vector2.new(0,math.max(0,entry.Frame.AbsolutePosition.Y-page.AbsolutePosition.Y+page.CanvasPosition.Y-80)) end\n            end)\n        end\n    end\nend\nSearchBox:GetPropertyChangedSignal(\"Text\"):Connect(refreshSearch)\nSearchButton.MouseButton1Click:Connect(function() SearchOverlay.Visible=true; SearchBox:CaptureFocus() end)\nSearchClose.MouseButton1Click:Connect(function() SearchOverlay.Visible=false end)\n\n--========================================================\n-- QUICK MENU (long press UltraNova mini button)\n--========================================================\nlocal QuickMenu=Instance.new(\"Frame\")\nQuickMenu.Size=UDim2.fromOffset(190,255); QuickMenu.Position=UDim2.new(0,16,.52,26); QuickMenu.BackgroundColor3=C.Space2; QuickMenu.Visible=false; QuickMenu.ZIndex=145; QuickMenu.Parent=Gui; corner(QuickMenu,15); stroke(QuickMenu,C.Purple,1.3,.08)\nlocal QL=Instance.new(\"UIListLayout\"); QL.Padding=UDim.new(0,6); QL.Parent=QuickMenu; padding(QuickMenu,8,8,8,8)\nlocal function qButton(text,fn) local b=Instance.new(\"TextButton\"); b.Size=UDim2.new(1,0,0,40); b.BackgroundColor3=C.Panel; b.Text=text; b.TextColor3=C.White; b.TextSize=11; b.Font=Enum.Font.GothamSemibold; b.ZIndex=146; b.Parent=QuickMenu; corner(b,9); b.MouseButton1Click:Connect(fn); return b end\nqButton(\"Fly ON/OFF\",function() S.fly=not S.fly; FlyPad.Visible=S.fly; toast(\"Fly: \"..(S.fly and \"ON\" or \"OFF\"),C.Purple) end)\nqButton(\"Noclip ON/OFF\",function() S.noclip=not S.noclip; toast(\"Noclip: \"..(S.noclip and \"ON\" or \"OFF\"),C.Cyan) end)\nqButton(\"ESP ON/OFF\",function() S.esp=not S.esp; refreshEsp(); toast(\"ESP: \"..(S.esp and \"ON\" or \"OFF\"),C.Cyan) end)\nqButton(\"Fullbright\",function() S.fullbright=not S.fullbright; if S.fullbright then Lighting.Brightness=3; Lighting.ClockTime=14; Lighting.GlobalShadows=false else Lighting.Brightness=original.Brightness; Lighting.ClockTime=original.ClockTime; Lighting.GlobalShadows=original.GlobalShadows end end)\nqButton(\"Open UltraNova\",function() QuickMenu.Visible=false; Mini.Visible=false; Main.Visible=true end)\n\nlocal miniHoldStart=0\nMini.InputBegan:Connect(function(input)\n    if input.UserInputType==Enum.UserInputType.Touch or input.UserInputType==Enum.UserInputType.MouseButton1 then\n        miniHoldStart=os.clock()\n        task.delay(.58,function()\n            if U.isMiniDragging() and not U.isMiniMoved() and os.clock()-miniHoldStart>=.55 then\n                QuickMenu.Position=UDim2.fromOffset(math.clamp(Mini.AbsolutePosition.X,4,Camera.ViewportSize.X-QuickMenu.AbsoluteSize.X-4),math.clamp(Mini.AbsolutePosition.Y+Mini.AbsoluteSize.Y+5,4,Camera.ViewportSize.Y-QuickMenu.AbsoluteSize.Y-4))\n                QuickMenu.Visible=not QuickMenu.Visible\n                U.setMiniMoved(true) -- prevents normal click opening the main window\n            end\n        end)\n    end\nend)\n\n-- Language snapshot after all controls exist.\ntask.defer(snapshotOriginalTexts)\n\n"},
    {"lifecycle","local UltraNovaGlobal = (getgenv and getgenv()) or _G\nlocal U = assert(UltraNovaGlobal.UltraNovaV32, \"UltraNova v3.2 core was not loaded\")\nlocal Players,UIS,RunService,TweenService,Lighting,SoundService,TeleportService,MarketplaceService,GuiService,VirtualUser,CoreGui,HttpService,Stats,ContentProvider,StarterGui = U.Players,U.UIS,U.RunService,U.TweenService,U.Lighting,U.SoundService,U.TeleportService,U.MarketplaceService,U.GuiService,U.VirtualUser,U.CoreGui,U.HttpService,U.Stats,U.ContentProvider,U.StarterGui\nlocal LP,Camera,unpackArgs = U.LP,U.Camera,U.unpackArgs\nlocal character,humanoid,root = U.character,U.humanoid,U.root\nlocal GuiParent,C,ESP_PALETTE = U.GuiParent,U.C,U.ESP_PALETTE\nlocal corner,stroke,gradient,padding = U.corner,U.stroke,U.gradient,U.padding\nlocal S,original = U.S,U.original\nlocal Gui,Main,Scale,refreshScale,Stars = U.Gui,U.Main,U.Scale,U.refreshScale,U.Stars\nlocal MainLineFX,restartMainLineTweens = U.MainLineFX,U.restartMainLineTweens\nlocal Header,NovaIcon,Title,SubTitle,Minimize,Mini,MiniLineFX,restartMiniLineTweens = U.Header,U.NovaIcon,U.Title,U.SubTitle,U.Minimize,U.Mini,U.MiniLineFX,U.restartMiniLineTweens\nlocal toast = U.toast\nlocal MenuAmbience,MenuWhoosh,syncMenuAudio = U.MenuAmbience,U.MenuWhoosh,U.syncMenuAudio\nlocal Sidebar,SideList,Content,Pages,Navs = U.Sidebar,U.SideList,U.Content,U.Pages,U.Navs\nlocal makePage,switchPage = U.makePage,U.switchPage\nlocal Home,Cheats,PlayersPage,CameraPage,VisualsPage,Emotes,Shaders,ServerPage,PerformancePage,ToolsPage,SettingsPage = U.Home,U.Cheats,U.PlayersPage,U.CameraPage,U.VisualsPage,U.Emotes,U.Shaders,U.ServerPage,U.PerformancePage,U.ToolsPage,U.SettingsPage\nlocal ControlRegistry,registerControl = U.ControlRegistry,U.registerControl\nlocal heading,section,card,infoCard,button,toggle,slider = U.heading,U.section,U.card,U.infoCard,U.button,U.toggle,U.slider\nlocal ModalDim,playerPicker = U.ModalDim,U.playerPicker\n\nlocal refreshEsp,clearEsp = U.refreshEsp,U.clearEsp\n\n--========================================================\n-- RESPAWN REAPPLY\n--========================================================\nLP.CharacterAdded:Connect(function()\n    task.wait(.8)\n\n    local h = humanoid()\n    if h then\n        h.WalkSpeed = S.speed\n        pcall(function()\n            h.UseJumpPower = true\n            h.JumpPower = S.jump\n        end)\n    end\n\n    workspace.Gravity = S.gravity\n\n    if S.localInvisible then\n        local c = character()\n        for _,d in ipairs(c:GetDescendants()) do\n            if d:IsA(\"BasePart\") then d.LocalTransparencyModifier = 1 end\n        end\n    end\n\n    if U.resetCollisionBackup then U.resetCollisionBackup() end\n    if refreshEsp then refreshEsp() end\nend)\n\n--========================================================\n-- CLEANUP WHEN HUB REMOVED\n--========================================================\nGui.AncestryChanged:Connect(function(_,parent)\n    if parent ~= nil then return end\n\n    S.fly = false\n    S.noclip = false\n    S.airWalk = false\n    S.esp = false\n    S.aimbot = false\n    S.silentAim = false\n\n    pcall(function()\n        if U.setFreecam then U.setFreecam(false) end\n    end)\n\n    pcall(function()\n        if U.AimOverlay then U.AimOverlay:Destroy() end\n    end)\n\n    pcall(function()\n        if U.stopDance then U.stopDance() end\n        if U.DanceSound then U.DanceSound:Destroy() end\n    end)\n\n    pcall(function()\n        if U.resetShader then U.resetShader() end\n    end)\n\n    pcall(function()\n        local folder=U.ShaderWorldFolder\n        if folder and folder.Parent then folder:Destroy() end\n    end)\n\n    pcall(function()\n        local air=U.getAirPlatform and U.getAirPlatform()\n        if air then air:Destroy() end\n    end)\n\n    pcall(function()\n        MenuAmbience:Destroy()\n        MenuWhoosh:Destroy()\n    end)\n\n    pcall(function()\n        if U.ExtraVisualGui then U.ExtraVisualGui:Destroy() end\n        if U.VisualWorldFolder then U.VisualWorldFolder:Destroy() end\n    end)\n\n    pcall(function()\n        if U.Radar then U.Radar:Destroy() end\n        if U.HealthMonitorHud then U.HealthMonitorHud:Destroy() end\n        if U.CoordHud then U.CoordHud:Destroy() end\n        if U.FreeCamPad then U.FreeCamPad:Destroy() end\n    end)\n\n    pcall(function()\n        local water=U.getWaterWalkPart and U.getWaterWalkPart()\n        if water then water:Destroy() end\n    end)\n\n    pcall(function()\n        if S.freezePosition and root() then root().Anchored=false end\n    end)\n\n    pcall(function()\n        StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.All,true)\n    end)\n\n    pcall(function()\n        if U.cleanupCheatPlus then U.cleanupCheatPlus() end\n        if U.cleanupAuraFx then U.cleanupAuraFx() end\n        if U.cleanupParkour then U.cleanupParkour() end\n    end)\n\n    if clearEsp then pcall(clearEsp) end\n    UltraNovaGlobal.UltraNovaV32 = nil\nend)\n\n--========================================================\n-- START\n--========================================================\nswitchPage(\"Home\")\ntoast(\"UltraNova Hub v3.2 ✦\",C.Purple)\n"},
}

for i,item in ipairs(MODULES) do
    local name,source=item[1],item[2]
    status(("Caricamento %d/%d • %s"):format(i,#MODULES,name))
    local chunk,compileErr=loadstring(source)
    if not chunk then
        fatal("COMPILE ERROR • "..name,compileErr)
        return
    end
    local ok,runErr=pcall(chunk)
    if not ok then
        fatal("RUNTIME ERROR • "..name,runErr)
        return
    end
    task.wait()
end

status("✅ UltraNova caricata")
task.delay(.7,function()
    if BootGui and BootGui.Parent then BootGui:Destroy() end
end)
